def evaluate(expr: str) -> float:
    """
    Evaluates an arithmetic expression containing non-negative numbers, +, -, *, / and parentheses,
    respecting operator precedence.

    Args:
        expr: The arithmetic expression string.

    Returns:
        The result of the expression.
    """
    def precedence(op):
        if op == '+' or op == '-':
            return 1
        elif op == '*' or op == '/':
            return 2
        return 0

    def apply_op(op, val1, val2):
        if op == '+':
            return val1 + val2
        elif op == '-':
            return val1 - val2
        elif op == '*':
            return val1 * val2
        elif op == '/':
            if val2 == 0:
                return float('nan')
            return val1 / val2
        else:
            return val1

    values = []
    ops = []
    i = 0
    while i < len(expr):
        if expr[i] == '(':
            ops.append(expr[i])
            i += 1
        elif expr[i].isdigit():
            val = 0
            while i < len(expr) and expr[i].isdigit():
                val = val * 10 + int(expr[i])
                i += 1
            values.append(val)
            i += 1
        elif expr[i] in '+-*/':
            while i < len(expr) and (expr[i] in '+-*/' or expr[i] == '(' or expr[i] == ')'):
                if expr[i] == '(':
                    ops.append(expr[i])
                    i += 1
                elif expr[i] == ')':
                    ops.pop()
                    i += 1
                else:
                    break
            i += 1
        else:
            i += 1

    result = float(values[0])
    for op in ops:
        result = apply_op(op, result, values[-1])
    return result
