def longest_unique_substring(s: str) -> int:
    left = 0
    max_len = 0
    last_occurrence = {}
    for right in range(len(s)):
        char = s[right]
        if char in last_occurrence:
            left = max(left, last_occurrence[char] + 1)
        last_occurrence[char] = right
        current_len = right - left + 1
        if current_len > max_len:
            max_len = current_len
    return max_len
